// Mushaf page data generated by scripts/convert-quran-pages.mjs.
import fs from "node:fs/promises";
import path from "node:path";
import { cache } from "react";

const DIR = path.join(process.cwd(), "data/quran-pages");

const load = cache(async <T>(file: string): Promise<T> =>
  JSON.parse(await fs.readFile(path.join(DIR, file), "utf8")),
);

export const MUSHAF_PAGES = 604;

/** [surah, ayah, QCF glyphs] — the part of one ayah drawn on one line. */
export type MushafSlice = [number, number, string];

export type MushafRow =
  | { t: "x" } // blank
  | { t: "h"; s: number } // surah banner
  | { t: "b"; s: number } // basmala
  /** Text line: `z` is the font scale that justifies it, `c` marks a centred (short) line. */
  | { t: "l"; z: number; c?: 1; s: MushafSlice[] };

export type MushafPage = {
  page: number;
  juz: number;
  hizb: number;
  quarter: number;
  surahs: number[];
  first: [number, number];
  last: [number, number];
  rows: MushafRow[];
};

export type MushafIndex = {
  fontExt: "woff2" | "ttf";
  /** Width of a justified line, in em of the page font. */
  lineWidth: number;
  pages: { juz: number; hizb: number; quarter: number; surah: number }[];
  surahs: { n: number; page: number }[];
  juz: { n: number; surah: number; ayah: number; page: number }[];
  quarters: { n: number; surah: number; ayah: number; page: number }[];
};

export const getMushafPage = (n: number) => load<MushafPage>(`${n}.json`);
export const getMushafIndex = () => load<MushafIndex>("index.json");
